const URL=HttpUrl,URLSearchParams=HttpParams,structuredClone=cloneJson;
const emailPolicy=(()=>{

// Client rules are data. No prompt-code rewriting or provider transport in this module.
const POLICY_VERSION = 'SAMPLE-initial-email-2026-10-08-v1';
const SENDER = Object.freeze({name:'Sample Sender',email:'person-94042af8@example.com'});
const SIGNATURE = `Warm regards,
Sample Sender, MPH, MHS, PA-C
Clinician | Advisor | Author | Podcaster | TEDx Speaker
Example Advisory, Inc.
251 Little Falls Drive
Wilmington, DE 19808
If you'd prefer no further emails from SAMPLE, reply 'no thanks' and we'll stop.`;
const VETTING = 'we vet early-stage healthcare companies before our members see them. We look at the market, financials, sales and whether the leadership team can execute.';
const SCORE_KEYS = Object.freeze(['overall','catalyst','core','circle','strategic']);
const CATEGORY = Object.freeze({catalyst:'Catalyst',core:'Core',circle:'Circle',strategic:'Strategic Partner'});
const KINDS = new Set(['specialty','current_role','past_role','board_role','board_certification','investing','practice_owner','organization_founder','executive','nonprofit_leader','research','publication','nickname']);
const BANNED = 'showcase underscore leverage tapestry landscape testament highlight foster enhance navigate groundbreaking transformative cutting-edge delve robust seamless elevate unlock pivotal crucial vibrant remarkable renowned innovative world-class journey ecosystem meaningful'.split(' ');
const str = value => typeof value === 'string' ? value.trim() : '';
function requireText(value, name) { if (!str(value)) throw new Error(`MISSING_${name}`); return value.trim(); }
function validateEvidence(value) {
  if (!value || !Array.isArray(value.sources) || !Array.isArray(value.claims)) throw new Error('INVALID_EVIDENCE');
  const ids = new Set();
  for (const source of value.sources) {
    requireText(source.id,'SOURCE_ID'); requireText(source.title,'SOURCE_TITLE');
    if (ids.has(source.id)) throw new Error('DUPLICATE_SOURCE_ID');
    ids.add(source.id);
    let url; try {url = new URL(source.url);} catch {throw new Error('INVALID_SOURCE_URL');}
    if (!['https:','http:'].includes(url.protocol) || url.username || url.password) throw new Error('INVALID_SOURCE_URL');
    if (!Number.isFinite(Date.parse(source.retrieved_at))) throw new Error('SOURCE_DATE_REQUIRED');
  }
  const claims = new Set();
  for (const claim of value.claims) {
    requireText(claim.id,'CLAIM_ID'); requireText(claim.text,'CLAIM_TEXT');
    if (claims.has(claim.id)) throw new Error('DUPLICATE_CLAIM_ID');
    claims.add(claim.id);
    if (!KINDS.has(claim.kind) || !['current','past','undated'].includes(claim.tense)) throw new Error('INVALID_CLAIM_KIND_OR_TENSE');
    if (!Array.isArray(claim.source_ids) || !claim.source_ids.length || claim.source_ids.some(id=>!ids.has(id))) throw new Error('UNLINKED_CLAIM');
    if (claim.kind === 'current_role' && claim.tense !== 'current') throw new Error('CURRENT_ROLE_TENSE_CONFLICT');
    if (claim.kind === 'past_role' && claim.tense !== 'past') throw new Error('PAST_ROLE_TENSE_CONFLICT');
