function aliasesFor(lead) {
  return [...new Set([lead.business_email,lead.personal_email,...(lead.aliases??[])].map(email).filter(validEmail))];
}
function exclusionReason(lead,snapshot) {
  const aliases=aliasesFor(lead);
  for(const row of [...snapshot.exclusions,...snapshot.enrollments]) {
    if((row.contact_id && row.contact_id===lead.contact_id)||(row.aliases??[]).map(email).some(v=>aliases.includes(v))||(row.domain && aliases.some(v=>{const domain=v.split('@')[1];return domain===email(row.domain)||domain.endsWith('.'+email(row.domain));}))) return text(row.reason)||'already-enrolled';
