  if(!Number.isFinite(Date.parse(now))) throw new Error('TIME_REQUIRED');
  if(!Array.isArray(inputs)||inputs.length<1||inputs.length>20) throw new Error('BATCH_MUST_BE_1_TO_20');
  for(const key of ['call_cap','cost_cap_usd','verification_max_age_days','snapshot_max_age_minutes']) if(typeof config[key]!=='number'||!Number.isFinite(config[key])||config[key]<0) throw new Error(`INVALID_CONFIG:${key}`);
